import{_ as o,a as r}from"./chunks/px4flow_offset.C3uUWFoE.js";import{_ as n,c as s,j as e,a,al as i,o as l}from"./chunks/framework.DCERqlYr.js";const b=JSON.parse('{"title":"광류 센서","description":"","frontmatter":{},"headers":[],"relativePath":"ko/sensor/optical_flow.md","filePath":"ko/sensor/optical_flow.md"}'),d={name:"ko/sensor/optical_flow.md"};function c(h,t,f,p,m,_){return l(),s("div",null,t[0]||(t[0]=[e("h1",{id:"광류-센서",tabindex:"-1"},[a("광류 센서 "),e("a",{class:"header-anchor",href:"#광류-센서","aria-label":'Permalink to "광류 센서"'},"​")],-1),e("p",null,[e("em",null,"Optical Flow"),a(" uses a downward facing camera and a downward facing distance sensor for velocity estimation. It can be used to determine speed when navigating without GNSS — in buildings, underground, or in any other GNSS-denied environment.")],-1),e("p",null,[a("The video below shows PX4 holding position using the "),e("a",{href:"./../dronecan/ark_flow.html"},"Ark Flow"),a(" sensor for velocity estimation in "),e("a",{href:"./../flight_modes_mc/position.html"},"Position Mode"),a(":")],-1),e("lite-youtube",{videoid:"aPQKgUof3Pc",title:"ARK Flow with PX4 Optical Flow Position Hold"},null,-1),i('<p>The image below shows an optical flow setup with a separate flow sensor (<a href="./../sensor/px4flow.html">PX4Flow</a>) and distance sensor (<a href="./../sensor/lidar_lite.html">Lidar-Lite</a>):</p><p><img src="'+o+'" alt="Optical flow lidar attached"></p><h2 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h2><p>An Optical Flow setup requires a downward facing camera and a downward facing <a href="./../sensor/rangefinders.html">distance sensor</a> (preferably a LiDAR). These can be combined in a single product, such as the <a href="./../dronecan/ark_flow.html">ARK Flow</a>, <a href="./../dronecan/ark_flow_mr.html">ARK Flow MR</a> and <a href="https://holybro.com/products/h-flow" target="_blank" rel="noreferrer">Holybro H-Flow</a>, or they may be separate sensors.</p><p>The sensor(s) can be connected via MAVLink, I2C or any other bus that supports the peripheral.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If connected to PX4 via MAVLink the Optical Flow camera sensor must publish the <a href="https://mavlink.io/en/messages/common.html#OPTICAL_FLOW_RAD" target="_blank" rel="noreferrer">OPTICAL_FLOW_RAD</a> message, and the distance sensor must publish the <a href="https://mavlink.io/en/messages/common.html#DISTANCE_SENSOR" target="_blank" rel="noreferrer">DISTANCE_SENSOR</a> message. The information is written to the corresponding uORB topics: <a href="./../msg_docs/DistanceSensor.html">DistanceSensor</a> and <a href="./../msg_docs/ObstacleDistance.html">ObstacleDistance</a>.</p></div><p>다른 방향으로 이동할 때의 흐름 출력은 다음과 같아야합니다.</p><table tabindex="0"><thead><tr><th>기체 이동</th><th>통합 흐름</th></tr></thead><tbody><tr><td>전방</td><td>+ Y</td></tr><tr><td>후방</td><td>- Y</td></tr><tr><td>우측</td><td>- X</td></tr><tr><td>좌측</td><td>+ X</td></tr></tbody></table><p>광류 데이터는 다른 속도 데이터 소스와 융합됩니다. The approach used for fusing sensor data and any offsets from the center of the vehicle must be configured in the <a href="#estimators">estimator</a>.</p><h3 id="scale-factor" tabindex="-1">Scale Factor <a class="header-anchor" href="#scale-factor" aria-label="Permalink to &quot;Scale Factor&quot;">​</a></h3><p>For pure rotations the <code>OPTICAL_FLOW_RAD.integrated_xgyro</code> and <code>OPTICAL_FLOW_RAD.integrated_x</code> (respectively <code>integrated_ygyro</code> and <code>integrated_y</code>) have to be the same. If this is not the case, the optical flow scale factor can be adjusted using <a href="./../advanced_config/parameter_reference.html#SENS_FLOW_SCALE">SENS_FLOW_SCALE</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The low resolution of common optical flow sensors can cause slow oscillations when hovering at a high altitude above ground (&gt; 20m). Reducing the optical flow scale factor can improve the situation.</p></div><h2 id="유량-센서-카메라" tabindex="-1">유량 센서/카메라 <a class="header-anchor" href="#유량-센서-카메라" aria-label="Permalink to &quot;유량 센서/카메라&quot;">​</a></h2><h3 id="ark-flow-ark-flow-mr" tabindex="-1">ARK Flow &amp; ARK Flow MR <a class="header-anchor" href="#ark-flow-ark-flow-mr" aria-label="Permalink to &quot;ARK Flow &amp; ARK Flow MR&quot;">​</a></h3><p><a href="./../dronecan/ark_flow.html">ARK Flow</a> is a <a href="./../dronecan/">DroneCAN</a> optical flow sensor, <a href="./../sensor/rangefinders.html">distance sensor</a>, and IMU. It has a PAW3902 optical flow sensor, Broadcom AFBR-S50LV85D 30 meter distance sensor, and Invensense ICM-42688-P 6-Axis IMU.</p><p><a href="./../dronecan/ark_flow_mr.html">ARK Flow MR</a> is a <a href="./../dronecan/">DroneCAN</a> optical flow sensor, <a href="./../sensor/rangefinders.html">distance sensor</a>, and IMU, for mid-range applications. It has a PixArt PAA3905 optical flow sensor, Broadcom AFBR-S50LX85D 50 meter distance sensor, and Invensense IIM-42653 6-Axis IMU.</p><h3 id="holybro-h-flow" tabindex="-1">Holybro H-Flow <a class="header-anchor" href="#holybro-h-flow" aria-label="Permalink to &quot;Holybro H-Flow&quot;">​</a></h3><p>The <a href="https://holybro.com/products/h-flow" target="_blank" rel="noreferrer">Holybro H-Flow</a> is a compact <a href="./../dronecan/">DroneCAN</a> optical flow and <a href="./../sensor/rangefinders.html">distance sensor</a> module. It combines a PixArt PAA3905 optical flow sensor, a Broadcom AFBR-S50LV85D distance sensor, and an InvenSense ICM-42688-P 6-axis IMU. An all-in-one design that simplifies installation, with an onboard infrared LED enhances visibility in low-light conditions.</p><h3 id="pmw3901-기반-센서" tabindex="-1">PMW3901 기반 센서 <a class="header-anchor" href="#pmw3901-기반-센서" aria-label="Permalink to &quot;PMW3901 기반 센서&quot;">​</a></h3><p><a href="./../sensor/pmw3901.html">PMW3901</a> is an optical flow tracking sensor similar to what you would find in a computer mouse, but adapted to work between 80 mm and infinity. Bitcraze, Tindie, Hex, Thone 및 Alientek의 일부 제품을 포함하여 여러 제품에 사용됩니다.</p><h3 id="기타-카메라-센서" tabindex="-1">기타 카메라 / 센서 <a class="header-anchor" href="#기타-카메라-센서" aria-label="Permalink to &quot;기타 카메라 / 센서&quot;">​</a></h3><p>카메라 통합 보드를 사용할 수 있습니다. For this the <a href="https://github.com/PX4/OpticalFlow" target="_blank" rel="noreferrer">Optical Flow repo</a> can be used (see also <a href="https://github.com/PX4/snap_cam" target="_blank" rel="noreferrer">snap_cam</a>).</p><h2 id="거리-측정기" tabindex="-1">거리 측정기 <a class="header-anchor" href="#거리-측정기" aria-label="Permalink to &quot;거리 측정기&quot;">​</a></h2><p>You can use any supported <a href="./../sensor/rangefinders.html">distance sensor</a>. 그러나 견고성과 정확성 측면에서는 음향 센서보다 LIDAR를 사용하는 것이 좋습니다.</p><h2 id="추정기" tabindex="-1">추정기 <a class="header-anchor" href="#추정기" aria-label="Permalink to &quot;추정기&quot;">​</a></h2><p>추정기는 광학 흐름 센서 및 기타 소스의 데이터를 융합합니다. 융합 방법 설정과 차량 중심에 대한 상대적 오프셋이 사용되는 추정기를 지정하여야합니다.</p><p>오프셋은 아래와 같이 차량 방향 및 중심을 기준으로 계산됩니다.</p><p><img src="'+r+'" alt="Optical Flow offsets"></p><p>Optical Flow based navigation is enabled by both <a href="#ekf2">EKF2</a> and LPE (deprecated).</p><h3 id="ekf2" tabindex="-1">Extended Kalman Filter (EKF2) <a class="header-anchor" href="#ekf2" aria-label="Permalink to &quot;Extended Kalman Filter (EKF2) {#ekf2}&quot;">​</a></h3><p>For optical flow fusion using EKF2, set <a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>.</p><p>광류 센서가 차량 중앙에서 오프셋된 경우 다음 매개변수를 사용하여 설정합니다.</p><table tabindex="0"><thead><tr><th>매개변수</th><th>설명</th></tr></thead><tbody><tr><td><a id="EKF2_OF_POS_X"></a><a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_X">EKF2_OF_POS_X</a></td><td>바디 프레임에서 광류 초점의 X 위치 (기본값은 0.0m).</td></tr><tr><td><a id="EKF2_OF_POS_Y"></a><a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_Y">EKF2_OF_POS_Y</a></td><td>바디 프레임에서 광류 초점의 Y 위치 (기본값은 0.0m).</td></tr><tr><td><a id="EKF2_OF_POS_Z"></a><a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_Z">EKF2_OF_POS_Z</a></td><td>바디 프레임에서 광류 초점의 Z 위치 (기본값은 0.0m).</td></tr></tbody></table><p>See <a href="./../advanced_config/tuning_the_ecl_ekf.html#optical-flow">Using PX4&#39;s Navigation Filter (EKF2) &gt; Optical flow</a> for more information.</p>',34)]))}const F=n(d,[["render",c]]);export{b as __pageData,F as default};
